func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestMax(t *testing.T) {
	tests := []struct {
		name string
		a, b int
		want int
	}{
		{name: "first larger", a: 3, b: 2, want: 3},
		{name: "second larger", a: 2, b: 3, want: 3},
		{name: "equal", a: 3, b: 3, want: 3},
		{name: "negatives", a: -5, b: -2, want: -2},
		{name: "zero and negative", a: 0, b: -1, want: 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := max(tt.a, tt.b); got != tt.want {
				t.Fatalf("max(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

